async function createUser(roleCode, suffix = '') {
  const role = await db.role.upsert({ where: { code: roleCode }, update: {}, create: { code: roleCode, name: roleCode } });
  return db.user.create({ data: { username: `${prefix}${roleCode}${suffix}`, displayName: roleCode === 'ADMIN' ? '后台验收管理员' : roleCode === 'HQ_FINANCE' ? '财务验收' : '供应商验收', passwordHash: await hashPassword(password), roles: { create: { roleId: role.id } } } });
}
