  await db.category.deleteMany({ where: { code: { startsWith: prefix }, parentId: { not: null } } });
  await db.category.deleteMany({ where: { code: { startsWith: prefix } } }); await db.unit.deleteMany({ where: { code: { startsWith: prefix } } });
